# Create 10x10 output with 4 hourglasses side-by-side in color order
# Each hourglass is 5x5, so 4*5 = 20 columns, but we'll make it 10x10 with proper packing

hourglass = [
    [c for c in range(5)], [c for c in range(5)], [c for c in range(5)], [c for c in range(5)]
]

def make_hourglass(color, size=5):
    return [
        [color, color, color, color, color],
        [0, 0, color, 0, 0],
        [0, color, color, color, 0],
        [color, color, color, color, color],
        [0, 0, color, 0, 0],
    ]

def concat_grids(grid1, grid2, vertical=False):
    if vertical:
        return [row1 + row2 for row1, row2 in zip(grid1, grid2)]
    else:
        return [row1 + row2 for row1, row2 in zip(grid1, grid2)]

color1 = make_hourglass(1)
color3 = make_hourglass(3)
color4 = make_hourglass(4)
color8 = make_hourglass(8)

# Side by side in color order
output = [color1[0][row] for row in range(5)]  # start with color1's row
try:
    # Horizontal concatenation
    output = concat_grids(color1, color3)
    output = concat_grids(output, color4) 
    output = concat_grids(output, color8)
    final = output
except:
    final = color1

# 10x10 grid - need to figure out proper layout
# Each shape is 5x5, but they're not perfectly square (hourglass shape)
# Put them in 2x2 arrangement
h1 = make_hourglass(1)
h3 = make_hourglass(3)
h4 = make_hourglass(4)
h8 = make_hourglass(8)

# Build 10x10 grid
grid = [[0]*10 for _ in range(10)]

